using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace Eldoria.ReferenceClean.Editor {
[InitializeOnLoad]
public static class ValoriaReferenceCleanPlayProbe {
 const string Flag="ValoriaReferenceClean.PlayProbe";static double entered;static int errors;
 static ValoriaReferenceCleanPlayProbe(){EditorApplication.playModeStateChanged+=Changed;UnityEngine.Application.logMessageReceived+=Log;}
 static void Log(string message,string stack,LogType type){if(SessionState.GetBool(Flag,false)&&(type==LogType.Exception||type==LogType.Error))errors++;}
 static string Fingerprint(string path){if(!File.Exists(path))return "ABSENT";using(var hash=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(hash.ComputeHash(File.ReadAllBytes(path)));}
 public static void Build(){SessionState.SetString(Flag+"CanonicalSave",Fingerprint(Eldoria.Presentation.SliceBoot.SavePath));SessionState.SetBool(Flag,true);SessionState.SetInt(Flag+"Result",0);EditorSceneManager.OpenScene("Assets/Eldoria/ArtTests/ValoriaReferenceClean/Valoria_Reference_Clean.unity",OpenSceneMode.Single);EditorApplication.EnterPlaymode();}
 static void Changed(PlayModeStateChange state){if(!SessionState.GetBool(Flag,false))return;if(state==PlayModeStateChange.EnteredPlayMode){entered=EditorApplication.timeSinceStartup;errors=0;EditorApplication.update+=Tick;}if(state==PlayModeStateChange.EnteredEditMode){bool pass=SessionState.GetInt(Flag+"Result",0)==1;SessionState.SetBool(Flag,false);if(pass){try{var root="Assets/Eldoria/ArtTests/ValoriaReferenceClean";var scene=root+"/Valoria_Reference_Clean.unity";var inputs=new[]{"Assets/Eldoria/Scripts/Presentation/SliceBoot.cs",scene,root+"/Prefabs/Bastion_I.prefab",root+"/Prefabs/FortifiedGate.prefab",root+"/Prefabs/MedievalBridge.prefab",root+"/Prefabs/BuildablePlots.prefab",root+"/Prefabs/Ruins.prefab"};var deps=AssetDatabase.GetDependencies(inputs,true).Where(p=>p.StartsWith("Assets/")).Distinct().ToArray();string package="../docs/evidence/valoria-reference-clean/Valoria_Reference_Clean.unitypackage";AssetDatabase.ExportPackage(deps,package,ExportPackageOptions.Default);if(new FileInfo(package).Length>80L*1024*1024)File.Delete(package);var backup="../docs/evidence/valoria-reference-clean/Valoria_Reference_Clean.blend1";if(File.Exists(backup))File.Delete(backup);}catch(Exception e){Debug.LogWarning("Optional package: "+e.Message);}}Debug.Log(pass?"VALORIA_REFERENCE_CLEAN_PLAY_COMPLETE":"VALORIA_REFERENCE_CLEAN_PLAY_FAILED");EditorApplication.Exit(pass?0:1);}}
 static void Tick(){if(EditorApplication.timeSinceStartup-entered<3)return;EditorApplication.update-=Tick;
 try {
 var interaction=UnityEngine.Object.FindFirstObjectByType<ValoriaReferenceCleanInteraction>();if(!interaction||!interaction.isActiveAndEnabled||!UnityEngine.Application.isPlaying)throw new Exception("Live PlayMode interaction missing");
 bool saveUntouched=Fingerprint(Eldoria.Presentation.SliceBoot.SavePath)==SessionState.GetString(Flag+"CanonicalSave","");if(!saveUntouched)throw new Exception("Canonical save changed");var cam=interaction.playerCamera;Physics.SyncTransforms();if(UnityEngine.Object.FindObjectsByType<Eldoria.Presentation.SlicePresenter>(FindObjectsSortMode.None).Length!=0||GameObject.Find("Eldoria composition root")!=null||GameObject.Find("Isometric camera")!=null)throw new Exception("Legacy auto-bootstrap contaminated the independent scene");int cameraCount=UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsSortMode.None).Count(c=>c.enabled);if(cameraCount!=1)throw new Exception("Unexpected active scene cameras: "+cameraCount);int count=0;
 foreach(var box in UnityEngine.Object.FindObjectsByType<BoxCollider>(FindObjectsSortMode.None).Where(c=>c.gameObject.layer==8)){
 var point=cam.WorldToScreenPoint(box.bounds.center);if(!Physics.Raycast(cam.ScreenPointToRay(point),out var hit,500,1<<8)||hit.collider!=box)throw new Exception("PlayMode ray selection: "+box.name);interaction.Select(hit.collider.name);if(box.name.StartsWith("Parcela")&&interaction.plot<1)throw new Exception("PlayMode parcel state missing");count++;
 }
 var routeFailures=new List<string>();int routePass=0,routeTotal=0;float lastHeight=0,maxStep=0;for(float z=-50;z<=25;z+=1){routeTotal++;if(Physics.Raycast(new Vector3(0,20,z),Vector3.down,out var h,40,~(1<<8),QueryTriggerInteraction.Ignore)&&h.point.y>-.1f&&h.point.y<1.2f){routePass++;if(routeTotal>1)maxStep=Mathf.Max(maxStep,Mathf.Abs(h.point.y-lastHeight));lastHeight=h.point.y;}else routeFailures.Add(z+":"+(h.collider?h.collider.name+"@"+h.point.y:"no surface"));}
 int stairsPass=0;for(int i=0;i<6;i++){if(Physics.Raycast(new Vector3(0,20,25.75f+i*.46f),Vector3.down,out var h,40,~(1<<8),QueryTriggerInteraction.Ignore)&&Mathf.Abs(h.point.y-(.57f+i*.19f))<.12f)stairsPass++;}
 if(routePass!=routeTotal||stairsPass!=6){foreach(var terrainCol in UnityEngine.Object.FindObjectsByType<TerrainCollider>(FindObjectsSortMode.None)){var data=terrainCol.terrainData;bool direct=terrainCol.Raycast(new Ray(new Vector3(0,20,14),Vector3.down),out var terrainHit,50);Debug.Log("TERRAIN_ROUTE_DIAGNOSTIC layer="+terrainCol.gameObject.layer+" enabled="+terrainCol.enabled+" bounds="+terrainCol.bounds+" data="+data+" solidCentre="+(data?data.GetHoles(128,128,1,1)[0,0]:false)+" directHit="+direct+" hit="+terrainHit.point);}}if(routePass!=routeTotal||stairsPass!=6)throw new Exception("Physical route or stairs fail: "+routePass+"/"+routeTotal+", stairs="+stairsPass+"; "+string.Join(";",routeFailures));
 float before=cam.orthographicSize;cam.orthographicSize=24;ValoriaReferenceCleanBuilder.Capture(cam,"../docs/evidence/valoria-reference-clean/playmode-zoom.png",1448,1086);cam.orthographicSize=before;
 var origin=cam.transform.position;cam.transform.position+=Vector3.right*6;ValoriaReferenceCleanBuilder.Capture(cam,"../docs/evidence/valoria-reference-clean/playmode-pan.png",1448,1086);cam.transform.position=origin;interaction.Select("Bastión I");
 ValoriaReferenceCleanBuilder.Capture(cam,"../docs/evidence/valoria-reference-clean/playmode-home.png",1448,1086);
 File.WriteAllText("../docs/evidence/valoria-reference-clean/playmode.json",JsonUtility.ToJson(new Report{playmode=true,canonical_save_untouched=saveUntouched,active_scene_cameras=cameraCount,legacy_boot_present=false,selectable_targets=count,route_probes=routeTotal,route_passes=routePass,stairs_passes=stairsPass,max_route_step=maxStep,zoom_camera_changed=true,pan_camera_changed=true,exceptions=errors,editor_batches=UnityStats.batches,editor_setpass_calls=UnityStats.setPassCalls,editor_triangles=UnityStats.triangles,physical_mobile_tested=false},true));
 if(count!=5||errors!=0)throw new Exception("Live probes fail: targets="+count+", errors="+errors);SessionState.SetInt(Flag+"Result",1);
 }catch(Exception e){Debug.LogException(e);SessionState.SetInt(Flag+"Result",0);}EditorApplication.ExitPlaymode();
 }
 [Serializable]class Report{public bool canonical_save_untouched;public bool legacy_boot_present;public int active_scene_cameras;public bool playmode,zoom_camera_changed,pan_camera_changed,physical_mobile_tested;public float max_route_step;public int route_probes,route_passes,stairs_passes,selectable_targets,exceptions,editor_batches,editor_setpass_calls,editor_triangles;}
}
}
